when.set-body:
@{
                    var row = context.Response.Body.As<JObject>();
                    var o = new JObject();
                    o["id"] = row["RowKey"];
                    o["name"] = row["name"];
                    o["email"] = row["email"];
                    if (row["city"] != null) { o["city"] = row["city"]; }
                    return o.ToString();
                }
